<form method="POST" action="{{ $user->exists ? route('admin-users.update', $user) : route('admin-users.store') }}"
    x-data="{ submitting: false, validation: $form(@js($user->exists ? 'put' : 'post'), @js($user->exists ? route('admin-users.update', $user) : route('admin-users.store')), { name: @js(old('name', $user->name)), email: @js(old('email', $user->email)), role: @js(old('role', $user->role ?: 'customer')), password: '', password_confirmation: '' }) }"
    class="space-y-5" @submit="submitting = true">
    @csrf
    @if ($user->exists) @method('PUT') @endif
    <div><label for="name" class="mb-1.5 block text-sm font-semibold text-slate-700">Nama lengkap</label><input id="name" name="name" type="text" required maxlength="255" value="{{ old('name', $user->name) }}" x-model="validation.name" @input.debounce.500ms="validation.validate('name')" class="w-full rounded-xl border-slate-200 text-sm focus:border-teal-500 focus:ring-teal-500">@error('name')<p class="mt-1 text-sm text-red-600">{{ $message }}</p>@enderror <p x-cloak x-show="validation.invalid('name')" x-text="validation.errors.name" class="mt-1 text-sm text-red-600"></p></div>
    <div><label for="email" class="mb-1.5 block text-sm font-semibold text-slate-700">Email</label><input id="email" name="email" type="email" required maxlength="255" value="{{ old('email', $user->email) }}" x-model="validation.email" @input.debounce.500ms="validation.validate('email')" class="w-full rounded-xl border-slate-200 text-sm focus:border-teal-500 focus:ring-teal-500">@error('email')<p class="mt-1 text-sm text-red-600">{{ $message }}</p>@enderror <p x-cloak x-show="validation.invalid('email')" x-text="validation.errors.email" class="mt-1 text-sm text-red-600"></p> @if ($user->exists)<p class="mt-1 text-xs text-slate-500">Mengubah email akan mengatur ulang status verifikasi email.</p>@endif</div>
    <div><label for="role" class="mb-1.5 block text-sm font-semibold text-slate-700">Role pengguna</label><select id="role" name="role" required x-model="validation.role" @change="validation.validate('role')" class="w-full rounded-xl border-slate-200 text-sm focus:border-teal-500 focus:ring-teal-500">@foreach ($roles as $value => $label)<option value="{{ $value }}" @selected(old('role', $user->role ?: 'customer') === $value)>{{ $label }}</option>@endforeach</select>@error('role')<p class="mt-1 text-sm text-red-600">{{ $message }}</p>@enderror <p x-cloak x-show="validation.invalid('role')" x-text="validation.errors.role" class="mt-1 text-sm text-red-600"></p><p class="mt-1 text-xs text-slate-500">Administrator memiliki akses penuh ke workspace admin.</p></div>
    <div class="border-t border-slate-100 pt-5"><h3 class="text-sm font-semibold text-slate-800">{{ $user->exists ? 'Ubah password (opsional)' : 'Password awal' }}</h3><p class="mt-1 text-xs text-slate-500">{{ $user->exists ? 'Kosongkan jika tidak ingin mengubah password.' : 'Gunakan password yang kuat dan sampaikan secara aman kepada pengguna.' }}</p><div class="mt-4 grid gap-4 sm:grid-cols-2"><div><label for="password" class="mb-1.5 block text-sm font-semibold text-slate-700">Password</label><input id="password" name="password" type="password" x-model="validation.password" @input.debounce.500ms="validation.validate('password')" @required(!$user->exists) autocomplete="new-password" class="w-full rounded-xl border-slate-200 text-sm focus:border-teal-500 focus:ring-teal-500">@error('password')<p class="mt-1 text-sm text-red-600">{{ $message }}</p>@enderror <p x-cloak x-show="validation.invalid('password')" x-text="validation.errors.password" class="mt-1 text-sm text-red-600"></p></div><div><label for="password_confirmation" class="mb-1.5 block text-sm font-semibold text-slate-700">Konfirmasi password</label><input id="password_confirmation" name="password_confirmation" type="password" x-model="validation.password_confirmation" @input.debounce.500ms="validation.validate('password')" @required(!$user->exists) autocomplete="new-password" class="w-full rounded-xl border-slate-200 text-sm focus:border-teal-500 focus:ring-teal-500"></div></div></div>
    <div class="flex flex-col-reverse gap-2 border-t border-slate-100 pt-5 sm:flex-row sm:justify-end"><a href="{{ route('admin-users.index') }}" class="rounded-xl border border-slate-200 px-4 py-2.5 text-center text-sm font-semibold text-slate-600 transition hover:bg-slate-50">Batal</a><button type="submit" :disabled="submitting" class="rounded-xl bg-teal-600 disabled:cursor-wait disabled:opacity-60 px-5 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-teal-700"><span x-text="submitting ? 'Menyimpan...' : '{{ $user->exists ? 'Simpan perubahan' : 'Buat pengguna' }}'">{{ $user->exists ? 'Simpan perubahan' : 'Buat pengguna' }}</span></button></div>
